record.field:
if inputs.get('VAC_TRUNCA_001') and inputs['VAC_TRUNCA_001'].amount > 0:
    result = inputs['VAC_TRUNCA_001'].amount
else:
    factores = payslip._rule_parameter('pe_regimen_factores')
    clave_regimen = version.labor_regime_id.clave_regimen or 'general'
    factor_vac = factores.get(clave_regimen, (1.0, 30, 30))[2] / 30.0

    computable = version.wage
    tiene_af = False
    for pariente in employee.relative_ids:
        nombre_relacion = (pariente.relation_id.name or '').lower()
        if 'hij' in nombre_relacion:
            limite_edad = pariente.max_age or 18
            if pariente.age < limite_edad or pariente.disability:
                tiene_af = True
                break
    if tiene_af:
        computable += payslip._rule_parameter('pe_asig_familiar')

    fecha_cese = version.contract_date_end
    inicio_contrato = version.contract_date_start or fecha_cese
    # Último aniversario del ingreso, no posterior al cese
    aniversario = inicio_contrato
    while aniversario + relativedelta(years=1) <= fecha_cese:
        aniversario = aniversario + relativedelta(years=1)

    meses = 0
    dias = 0
    cursor = date(aniversario.year, aniversario.month, 1)
    if aniversario.day > 1:
        fin_mes_parcial = cursor + relativedelta(months=1, days=-1)
        if fin_mes_parcial <= fecha_cese:
            dias += min(30, (fin_mes_parcial - aniversario).days + 1)
        cursor = cursor + relativedelta(months=1)
    while cursor <= fecha_cese:
        fin_mes = cursor + relativedelta(months=1, days=-1)
        if fin_mes <= fecha_cese:
            meses += 1
        else:
            dias += (fecha_cese - cursor).days + 1
        cursor = cursor + relativedelta(months=1)

    result = computable * factor_vac * (meses / 12.0 + dias / 360.0)

if inputs.get('GRATI_TRUNCA_001') and inputs['GRATI_TRUNCA_001'].amount > 0:
    result = inputs['GRATI_TRUNCA_001'].amount
else:
    factores = payslip._rule_parameter('pe_regimen_factores')
    clave_regimen = version.labor_regime_id.clave_regimen or 'general'
    factor = factores.get(clave_regimen, (1.0, 30, 30))[0]

    computable = version.wage
    tiene_af = False
    for pariente in employee.relative_ids:
        nombre_relacion = (pariente.relation_id.name or '').lower()
        if 'hij' in nombre_relacion:
            limite_edad = pariente.max_age or 18
            if pariente.age < limite_edad or pariente.disability:
                tiene_af = True
                break
    if tiene_af:
        computable += payslip._rule_parameter('pe_asig_familiar')

    fecha_cese = version.contract_date_end
    anio = fecha_cese.year
    if fecha_cese.month <= 6:
        inicio_semestre = date(anio, 1, 1)
    else:
        inicio_semestre = date(anio, 7, 1)
    inicio_contrato = version.contract_date_start or inicio_semestre
    inicio_computo = inicio_contrato if inicio_contrato > inicio_semestre else inicio_semestre

    meses = 0
    cursor = date(inicio_computo.year, inicio_computo.month, 1)
    if inicio_computo.day > 1:
        cursor = cursor + relativedelta(months=1)
    while cursor <= fecha_cese:
        fin_mes = cursor + relativedelta(months=1, days=-1)
        if fin_mes <= fecha_cese:
            meses += 1
        cursor = cursor + relativedelta(months=1)

    result = computable * factor * min(meses, 6) / 6.0

if employee.management_eps:
    tasa = payslip._rule_parameter('pe_grati_bono_eps')
else:
    tasa = payslip._rule_parameter('pe_grati_bono_essalud')
result = result_rules['GRATI_TRUNCA_001']['total'] * tasa

if inputs.get('CTS_TRUNCA_001') and inputs['CTS_TRUNCA_001'].amount > 0:
    result = inputs['CTS_TRUNCA_001'].amount
else:
    factores = payslip._rule_parameter('pe_regimen_factores')
    clave_regimen = version.labor_regime_id.clave_regimen or 'general'
    factor = factores.get(clave_regimen, (1.0, 30, 30))[1] / 30.0

    fecha_cese = version.contract_date_end
    anio = fecha_cese.year
    if fecha_cese.month <= 4:
        inicio_periodo = date(anio - 1, 11, 1)
    elif fecha_cese.month <= 10:
        inicio_periodo = date(anio, 5, 1)
    else:
        inicio_periodo = date(anio, 11, 1)

    computable = version.wage
    tiene_af = False
    for pariente in employee.relative_ids:
        nombre_relacion = (pariente.relation_id.name or '').lower()
        if 'hij' in nombre_relacion:
            limite_edad = pariente.max_age or 18
            if pariente.age < limite_edad or pariente.disability:
                tiene_af = True
                break
    if tiene_af:
        computable += payslip._rule_parameter('pe_asig_familiar')
    grati_percibida = payslip._sum('GRATI_001', inicio_periodo, fecha_cese)
    computable += grati_percibida / 6.0

    inicio_contrato = version.contract_date_start or inicio_periodo
    inicio_computo = inicio_contrato if inicio_contrato > inicio_periodo else inicio_periodo

    meses = 0
    dias = 0
    cursor = date(inicio_computo.year, inicio_computo.month, 1)
    if inicio_computo.day > 1:
        fin_mes_parcial = cursor + relativedelta(months=1, days=-1)
        if fin_mes_parcial <= fecha_cese:
            dias += min(30, (fin_mes_parcial - inicio_computo).days + 1)
        cursor = cursor + relativedelta(months=1)
    while cursor <= fecha_cese:
        fin_mes = cursor + relativedelta(months=1, days=-1)
        if fin_mes <= fecha_cese:
            meses += 1
        else:
            dias += (fecha_cese - cursor).days + 1
        cursor = cursor + relativedelta(months=1)

    result = computable * factor * (meses / 12.0 + dias / 360.0)
